package api

import "github.com/lordbagel42/bambu-rea/pkg/bambu/cloud"

// cloudEndpointDescription documents the upstream operation, not a local printer
// command. Keys deliberately include the verb: reading a resource and changing
// it often have very different consequences. These descriptions are inferred
// from the shipped Handy interfaces and models, not live service verification.
func cloudEndpointDescription(ep *cloud.Endpoint) string {
	const prefix = "Advanced Bambu cloud passthrough, not an ordinary printer-control route. "
	if ep == nil {
		return prefix + "No upstream endpoint metadata is available; the operation's purpose is unknown."
	}
	description, ok := cloudOperationDescriptions[ep.Method+" "+ep.Path]
	if !ok {
		description = "This upstream operation has not yet been documented. Its purpose and side effects are unknown; inspect the upstream request contract before using it."
	}
	if ep.Signed {
		description += " Bambu app/device signing is required in addition to the applicable account credentials."
	}
	return prefix + description + " Purpose inferred from Handy's shipped API contract; upstream availability and permission rules may vary."
}

